import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Extract image URL from config assets
  const imageUrl = config.assets?.imageUrl;
  if (!imageUrl) {
    group.userData.cleanup = () => {};
    group.userData.handlers = {};
    return group;
  }

  // Load texture asynchronously via cached loader
  const map = ctx.textureLoader.load(imageUrl);

  // Atlas region dimensions: 512x320 pixels
  // Calculate plane dimensions to maintain aspect ratio
  const aspectRatio = 512 / 320;
  const planeHeight = 1;
  const planeWidth = planeHeight * aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Create material using TSL texture node
  const colorNode = texture(map);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position and transformation from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    mesh.position.set(x, y, z);

    if (rotationXYZ) {
      const [rx = 0, ry = 0, rz = 0] = rotationXYZ;
      mesh.rotation.set(rx, ry, rz);
    }

    if (scaleXYZ) {
      const [sx = 1, sy = 1, sz = 1] = scaleXYZ;
      mesh.scale.set(sx, sy, sz);
    }
  }

  group.add(mesh);

  // Attach cleanup handler to dispose all resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    map.dispose();
  };

  // Attach event handlers (none for this static element)
  group.userData.handlers = {};

  return group;
}
